--- /dev/null
+++ b/crates/sutura-exec-datafusion/src/combine/across/task_context.rs
@@ -0,0 +1,242 @@
+//! Local task/grant context only. This module promotes no remote refusal to a number.
+
+use std::collections::HashMap;
+use std::fmt;
+use std::sync::Arc;
+
+use datafusion::arrow::array::RecordBatch;
+use datafusion::common::tree_node::{TreeNode as _, TreeNodeRecursion};
+use datafusion::error::DataFusionError;
+use datafusion::execution::{SendableRecordBatchStream, TaskContext};
+use datafusion::physical_plan::stream::RecordBatchStreamAdapter;
+use datafusion_distributed::{
+    CoordinatorToWorkerMsg, ExecuteTaskRequest, GetWorkerInfoRequest, GetWorkerInfoResponse, MaybeEncoded, SetPlanRequest,
+    TaskKey, WorkerChannel, WorkerToCoordinatorMsg,
+};
+use futures_util::stream::BoxStream;
+use futures_util::{StreamExt as _, TryStreamExt as _};
+use parking_lot::Mutex;
+use ring::digest;
+use tonic::codegen::http::HeaderMap;
+
+use super::partition::PartitionScanExec;
+
+#[cfg(test)]
+pub(in crate::combine) mod inspection;
+
+#[derive(Clone, Copy)]
+pub(super) struct IssuedRead {
+    fingerprint: [u8; 32],
+    rows: u32,
+    bytes: u32,
+}
+
+impl IssuedRead {
+    pub(super) fn at_mint(grant: &[u8], (rows, bytes): (u32, u32)) -> Self {
+        let mut fingerprint = [0; 32];
+        fingerprint.copy_from_slice(digest::digest(&digest::SHA256, grant).as_ref());
+        Self {
+            fingerprint,
+            rows,
+            bytes,
+        }
+    }
+
+    pub(super) fn names(&self, grant: &[u8]) -> bool {
+        digest::digest(&digest::SHA256, grant).as_ref() == self.fingerprint.as_slice()
+    }
+}
+
+impl fmt::Debug for IssuedRead {
+    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
+        f.debug_struct("IssuedRead")
+            .field("rows", &self.rows)
+            .field("bytes", &self.bytes)
+            .finish_non_exhaustive()
+    }
+}
+
+struct Submitted {
+    task: TaskKey,
+    reads: Vec<IssuedRead>,
+}
+
+struct State {
+    tasks: HashMap<TaskKey, Arc<Submitted>>,
+    used: usize,
+}
+
+pub(super) struct Retained {
+    max_entries: usize,
+    state: Mutex<Option<State>>,
+}
+
+impl Retained {
+    pub(super) fn new(max_entries: usize) -> Self {
+        Self {
+            max_entries,
+            state: Mutex::new(Some(State {
+                tasks: HashMap::new(),
+                used: 0,
+            })),
+        }
+    }
+
+    fn close(&self) {
+        *self.state.lock() = None;
+    }
+
+    fn register(&self, request: &SetPlanRequest) {
+        let MaybeEncoded::Decoded(plan) = &request.plan else {
+            self.close();
+            return;
+        };
+        let mut reads = Vec::new();
+        let mut known = true;
+        let walked = plan.apply(|node| {
+            if let Some(scan) = node.downcast_ref::<PartitionScanExec>() {
+                match scan.issued_read() {
+                    Some(read) if reads.len() < self.max_entries => reads.push(read),
+                    _ => known = false,
+                }
+            }
+            Ok(if known {
+                TreeNodeRecursion::Continue
+            } else {
+                TreeNodeRecursion::Stop
+            })
+        });
+        let mut state = self.state.lock();
+        let Some(active) = state.as_mut() else { return };
+        let needed = reads.len().saturating_add(1);
+        if walked.is_err()
+            || !known
+            || active.tasks.contains_key(&request.task_key)
+            || active.tasks.keys().any(|key| key.query_id != request.task_key.query_id)
+            || active.used.saturating_add(needed) > self.max_entries
+        {
+            *state = None;
+            return;
+        }
+        if reads.is_empty() {
+            return;
+        }
+        active.used += needed;
+        active.tasks.insert(
+            request.task_key,
+            Arc::new(Submitted {
+                task: request.task_key,
+                reads,
+            }),
+        );
+    }
+
+    fn failure(&self, task: TaskKey, cause: DataFusionError) -> DataFusionError {
+        let submitted = self.state.lock().as_ref().and_then(|state| state.tasks.get(&task)).cloned();
+        match submitted {
+            Some(submitted) => DataFusionError::External(Box::new(Failure { submitted, cause })),
+            None => cause,
+        }
+    }
+}
+
+#[derive(thiserror::Error)]
+#[error("a remote task failed")]
+struct Failure {
+    submitted: Arc<Submitted>,
+    #[source]
+    cause: DataFusionError,
+}
+
+impl fmt::Debug for Failure {
+    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
+        f.debug_struct("TaskFailure")
+            .field("task", &self.submitted.task)
+            .field("reads", &self.submitted.reads)
+            .finish_non_exhaustive()
+    }
+}
+
+pub(super) struct Closing(Arc<Retained>);
+
+impl Closing {
+    pub(super) fn new(retained: Arc<Retained>) -> Self {
+        Self(retained)
+    }
+}
+
+impl Drop for Closing {
+    fn drop(&mut self) {
+        self.0.close();
+    }
+}
+
+pub(super) fn scoped(stream: SendableRecordBatchStream, closing: Closing) -> SendableRecordBatchStream {
+    let schema = stream.schema();
+    let stream = futures_util::stream::unfold((stream, closing), |(mut stream, closing)| async move {
+        let item = stream.next().await?;
+        if item.is_err() {
+            closing.0.close();
+        }
+        Some((item, (stream, closing)))
+    });
+    Box::pin(RecordBatchStreamAdapter::new(schema, stream))
+}
+
+pub(super) struct Channel(pub(super) Box<dyn WorkerChannel>);
+
+#[async_trait::async_trait]
+impl WorkerChannel for Channel {
+    async fn coordinator_channel(
+        &mut self,
+        headers: HeaderMap,
+        request: SetPlanRequest,
+        outbound: BoxStream<'static, CoordinatorToWorkerMsg>,
+        metrics: datafusion::physical_plan::metrics::ExecutionPlanMetricsSet,
+        ctx: &Arc<TaskContext>,
+    ) -> Result<BoxStream<'static, Result<WorkerToCoordinatorMsg, DataFusionError>>, DataFusionError> {
+        #[cfg(test)]
+        inspection::submitted(ctx, &request);
+        if let Some(retained) = ctx.session_config().get_extension::<Retained>() {
+            retained.register(&request);
+        }
+        self.0.coordinator_channel(headers, request, outbound, metrics, ctx).await
+    }
+
+    async fn execute_task(
+        &mut self,
+        headers: HeaderMap,
+        request: ExecuteTaskRequest,
+        metrics: datafusion::physical_plan::metrics::ExecutionPlanMetricsSet,
+        ctx: &Arc<TaskContext>,
+    ) -> Result<Vec<BoxStream<'static, Result<RecordBatch, DataFusionError>>>, DataFusionError> {
+        let retained = ctx.session_config().get_extension::<Retained>();
+        let task = request.task_key;
+        #[cfg(test)]
+        inspection::requested(ctx, task);
+        let streams = self
+            .0
+            .execute_task(headers, request, metrics, ctx)
+            .await
+            .map_err(|cause| match &retained {
+                Some(scope) => scope.failure(task, cause),
+                None => cause,
+            })?;
+        Ok(streams
+            .into_iter()
+            .map(|stream| {
+                let retained = retained.clone();
+                stream
+                    .map_err(move |cause| match &retained {
+                        Some(scope) => scope.failure(task, cause),
+                        None => cause,
+                    })
+                    .boxed()
+            })
+            .collect())
+    }
+
+    async fn get_worker_info(&mut self, request: GetWorkerInfoRequest) -> Result<GetWorkerInfoResponse, DataFusionError> {
+        self.0.get_worker_info(request).await
+    }
+}
