+
+use super::{Authority, listening, roomy, served, servers};
+use crate::combine::across::{executing, inspection, relayed};
+use crate::combine::{CombineError, Nodes, PartitionReader, SplitScan, StreamBound, Unread};
+
+struct Refusing(Arc<AtomicUsize>);
+
+impl PartitionReader for Refusing {
+    fn read(
+        &self,
+        _: &sutura_domain::identity::VerifierId,
+        _: &[u8],
+        source: &SourceName,
+        partition: &[u8],
+        schema: &SchemaRef,
+        capture: Option<crate::SubmissionCapture>,
+    ) -> Result<SendableRecordBatchStream, Unread> {
+        self.0.fetch_add(1, Ordering::SeqCst);
+        if let Some(capture) = capture {
+            let mut facts = ResultBatches::none_under(Arc::clone(schema)).with_execution(Execution::DataFusion {
+                source: Some(source.clone()),
+                stage: PlanStage::Files,
+                logical_plan: format!("fixture native partition {partition:?}"),
+            });
+            capture.begin()?.complete(&mut facts)?;
+        }
+        let batch = RecordBatch::try_new(Arc::clone(schema), vec![Arc::new(Int64Array::from(vec![1_i64]))])
+            .expect("the fake source supplies one integer");
+        let failure = (partition == [0]).then_some(Unread::DidNotFit);
+        let ending = Arc::clone(schema);
+        Ok(Box::pin(RecordBatchStreamAdapter::new(
+            Arc::clone(schema),
+            stream::iter([Ok(batch)]).chain(crate::read_later(Arc::clone(schema), async move {
+                match failure {
+                    Some(refusal) => Err(refusal),
+                    None => Ok(ResultBatches::none_under(ending)),
+                }
+            })),
+        )))
+    }
+}
+
+struct Native {
+    servers: Runtime,
+    planning: SessionContext,
+    trace: Arc<inspection::Trace>,
+    reads: Arc<AtomicUsize>,
+    requests: Vec<Arc<AtomicUsize>>,
+}
+
+impl Native {
+    fn new() -> Self {
+        let servers = servers();
+        let authority = Authority::generate();
+        let node = authority.sign();
+        let own = Nodes::worker(roomy(), authority.identity(&node)).expect("the planning worker builds");
+        let own_url = served(&servers, listening(&node, authority.peers()), own.clone(), Arc::default());
+        let reads = Arc::new(AtomicUsize::new(0));
+        let mut requests = Vec::new();
+        let peers: Vec<_> = (0..2)
+            .map(|_| {
+                let signed = authority.sign();
+                let reader: Arc<dyn PartitionReader> = Arc::new(Refusing(Arc::clone(&reads)));
+                let worker = Nodes::worker_reading(roomy(), authority.identity(&signed), Some(reader))
+                    .expect("the native reading worker builds");
+                let sent = Arc::new(AtomicUsize::new(0));
+                let url = served(&servers, listening(&signed, authority.peers()), worker, Arc::clone(&sent));
+                requests.push(sent);
+                url
+            })
+            .collect();
+        let source = SourceName::parse("orders").expect("the fixture source parses");
+        let planning = Nodes::declared(own, own_url, peers.clone(), authority.identity(&node))
+            .reading(source, peers)
+            .session(roomy())
+            .expect("the product distributed session builds");
+        let trace = Arc::new(inspection::Trace::default());
+        let mut builder = SessionStateBuilder::new_from_existing(planning.state());
+        let config = builder.config().take().unwrap_or_default().with_extension(Arc::clone(&trace));
+        let planning = SessionContext::new_with_state(builder.with_config(config).build());
+        Self {
+            servers,
+            planning,
+            trace,
+            reads,
+            requests,
+        }
+    }
+
+    fn fail(&self, rows: u32, resign: bool) -> (DataFusionError, Vec<[u8; 32]>) {
+        let schema = Arc::new(Schema::new(vec![Field::new("n", DataType::Int64, false)]));
+        let source = SourceName::parse("orders").expect("the fixture source parses");
+        let caller = Subject::verified("user@example.com").expect("the fixture subject parses");
+        let scan = SplitScan::granted(
+            format!("native-own-grant-{rows}").into_bytes(),
+            source,
+            schema,
+            (0_u8..6).map(|index| vec![index]),
+            &caller,
+            SystemTime::now() + Duration::from_secs(3600),
+            StreamBound::new(rows, rows * 1024),
+        )
+        .expect("the real product mint grants six partitions");
+        let minted = scan.fingerprints();
+        let scan = if resign { scan.resigned() } else { scan };
+        let error = self.servers.block_on(async {
+            tokio::time::timeout(Duration::from_secs(30), async {
+                let frame = self
+                    .planning
+                    .read_table(Arc::new(scan))
+                    .expect("the granted table plans")
+                    .sort(vec![col("n").sort(true, false)])
+                    .expect("the native stage sorts");
+                let (mut output, _) = executing(frame, roomy())
+                    .await
+                    .expect("the product root creates its physical attempt");
+                let mut failure = None;
+                while let Some(batch) = output.next().await {
+                    if let Err(cause) = batch {
+                        failure = Some(cause);
+                        break;
+                    }
+                }
+                drop(output);
+                failure.expect("the native fake reader fails after a batch")
+            })
+            .await
+            .expect("the native attempt terminates within its fixture deadline")
+        });
+        (error, minted)
+    }
+}
+
+#[test]
+fn a_native_failed_task_keeps_its_exact_locally_issued_read_set() {
+    let native = Native::new();
+    let mut previous = None;
+    let mut previous_mints = Vec::new();
+    for rows in [7, 11] {
+        let (error, minted) = native.fail(rows, false);
+        let observed = inspection::failure(&error);
+        assert!(
+            observed.is_some(),
+            "native failed read lost its locally retained task and mint set: {error:?}"
+        );
+        let (task, mut facts) = observed.expect("the preceding own assertion requires a local frame");
+        let submitted = native.trace.submitted();
+        let mut expected = submitted
+            .iter()
+            .find(|(key, _)| *key == task)
+            .expect("the failure names an actual native submission")
+            .1
+            .clone();
+        facts.sort_unstable();
+        expected.sort_unstable();
+        assert_eq!(
+            facts, expected,
+            "the failure must retain exactly its own native task's full read set"
+        );
+        assert_eq!(facts.len(), 3, "each of two tasks must own three of six partition reads");
+        assert!(
+            facts.iter().any(|(read, _, _)| *read == minted[0]),
+            "the failed native task must own the partition that actually refused"
+        );
+        assert!(
+            native.trace.requested().contains(&task),
+            "the failure must name the locally requested native task"
+        );
+        assert!(
+            facts
+                .iter()
+                .all(|(fingerprint, r, bytes)| minted.contains(fingerprint) && *r == rows && *bytes == rows * 1024)
+        );
+        let other: Vec<_> = submitted
+            .iter()
+            .filter(|(key, reads)| key.query_id == task.query_id && *key != task && !reads.is_empty())
+            .flat_map(|(_, reads)| reads)
+            .collect();
+        assert!(!other.is_empty(), "another native task must hold the other mint set");
+        assert!(
+            other.iter().all(|read| !facts.contains(read)),
+            "a query-wide mint union must not fit this failure"
+        );
+        if let Some(query) = previous {
+            assert_ne!(
+                task.query_id, query,
+                "newly planned physical attempts require different native query keys"
+            );
+            assert!(
+                minted.iter().all(|read| !previous_mints.contains(read)),
+                "a fresh mint must not reuse prior grant bytes"
+            );
+        }
+        previous = Some(task.query_id);
+        previous_mints = minted;
+        assert!(
+            matches!(
+                relayed(CombineError::Execute { cause: error }),
+                CombineError::PartitionDidNotFit
+            ),
+            "reader DidNotFit must remain the existing numberless refusal"
+        );
+        assert!(native.trace.scope_count() > 0);
+        assert_eq!(
+            native.trace.closed_scopes(),
+            native.trace.scope_count(),
+            "a terminal stream must close optional retention"
+        );
+    }
+    assert_eq!(
+        native.trace.scope_count(),
+        2,
+        "each physical attempt needs its own optional scope"
+    );
+    assert!(
+        native.reads.load(Ordering::SeqCst) > 0,
+        "real native admission must reach the fake port"
+    );
+    assert!(
+        native.requests.iter().all(|sent| sent.load(Ordering::SeqCst) > 0),
+        "both peers must receive actual native RPCs"
+    );
+}
+
+#[test]
+fn a_native_worker_valid_resign_cannot_acquire_local_issuance() {
+    let native = Native::new();
+    let (original, _) = native.fail(7, false);
+    assert!(
+        inspection::failure(&original).is_some(),
+        "native original mint must establish the local frame before the resign attack: {original:?}"
+    );
+    let before = native.reads.load(Ordering::SeqCst);
+    let (resigned, _) = native.fail(11, true);
+    assert!(
+        native.reads.load(Ordering::SeqCst) > before,
+        "the actual worker must admit the grant re-signed under its real key"
+    );
+    assert!(
+        inspection::failure(&resigned).is_none(),
+        "a changed signed bound must invalidate the original local mint marker"
+    );
+    assert!(
+        matches!(
+            relayed(CombineError::Execute { cause: resigned }),
+            CombineError::PartitionDidNotFit
+        ),
+        "an uncorrelated reader DidNotFit stays numberless"
+    );
+    assert_eq!(native.trace.closed_scopes(), native.trace.scope_count());
+}

