+//! Test-only observations of the real submitted plan and requested native task.
+
+use std::sync::Arc;
+
+use datafusion::common::tree_node::{TreeNode as _, TreeNodeRecursion};
+use datafusion::error::DataFusionError;
+use datafusion::execution::TaskContext;
+use datafusion_distributed::{MaybeEncoded, SetPlanRequest, TaskKey};
+use parking_lot::Mutex;
+use ring::digest;
+
+use super::{Failure, Retained};
+use crate::combine::across::{chain, grant, partition::PartitionScanExec};
+
+pub(in crate::combine) type Fact = ([u8; 32], u32, u32);
+
+#[derive(Default)]
+pub(in crate::combine) struct Trace {
+    submitted: Mutex<Vec<(TaskKey, Vec<Fact>)>>,
+    requested: Mutex<Vec<TaskKey>>,
+    // Keep scopes alive so closure cannot pass merely because the last owner disappeared.
+    scopes: Mutex<Vec<Arc<Retained>>>,
+}
+
+impl Trace {
+    pub(in crate::combine) fn submitted(&self) -> Vec<(TaskKey, Vec<Fact>)> {
+        self.submitted.lock().clone()
+    }
+
+    pub(in crate::combine) fn requested(&self) -> Vec<TaskKey> {
+        self.requested.lock().clone()
+    }
+
+    pub(in crate::combine) fn closed_scopes(&self) -> usize {
+        self.scopes.lock().iter().filter(|scope| scope.state.lock().is_none()).count()
+    }
+
+    pub(in crate::combine) fn scope_count(&self) -> usize {
+        self.scopes.lock().len()
+    }
+}
+
+pub(super) fn submitted(ctx: &Arc<TaskContext>, request: &SetPlanRequest) {
+    let Some(trace) = ctx.session_config().get_extension::<Trace>() else {
+        return;
+    };
+    let MaybeEncoded::Decoded(plan) = &request.plan else { return };
+    let mut facts = Vec::new();
+    plan.apply(|node| {
+        if let Some(encoded) = node
+            .downcast_ref::<PartitionScanExec>()
+            .and_then(PartitionScanExec::encoded_grant)
+        {
+            let mut fingerprint = [0; 32];
+            fingerprint.copy_from_slice(digest::digest(&digest::SHA256, encoded).as_ref());
+            let (rows, bytes) = grant::signed_bound(encoded);
+            facts.push((fingerprint, rows, bytes));
+        }
+        Ok(TreeNodeRecursion::Continue)
+    })
+    .expect("the test observes the submitted native plan");
+    trace.submitted.lock().push((request.task_key, facts));
+    if let Some(retained) = ctx.session_config().get_extension::<Retained>() {
+        let mut scopes = trace.scopes.lock();
+        if !scopes.iter().any(|known| Arc::ptr_eq(known, &retained)) {
+            scopes.push(retained);
+        }
+    }
+}
+
+pub(super) fn requested(ctx: &Arc<TaskContext>, task: TaskKey) {
+    if let Some(trace) = ctx.session_config().get_extension::<Trace>() {
+        trace.requested.lock().push(task);
+    }
+}
+
+pub(in crate::combine) fn failure(error: &DataFusionError) -> Option<(TaskKey, Vec<Fact>)> {
+    let failure = chain(error).find_map(|cause| cause.downcast_ref::<Failure>())?;
+    Some((
+        failure.submitted.task,
+        failure
+            .submitted
+            .reads
+            .iter()
+            .map(|read| (read.fingerprint, read.rows, read.bytes))
+            .collect(),
+    ))
+}
